contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint16 feeRate,
        uint256 outputAmount
    ) public {
        require(feeRate <= 5_000);
        require(virtualNftReserves > outputAmount);
        require(outputAmount <= type(uint128).max);
        require(virtualBaseTokenReserves <= type(uint128).max / 1_000_000);
        require(outputAmount < type(uint256).max / (1_000_000 * 5_000));

        c.initialize(
            address(0x1),
            address(0x2),
            virtualBaseTokenReserves,
            virtualNftReserves,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.buyQuote(outputAmount);

        uint256 expectedProtocolFee = uint256(outputAmount) * c.factoryProtocolFeeRateValue() / 10_000;

        assert(
            feeAmount == uint256(outputAmount) * feeRate / 10_000 &&
            protocolFeeAmount == expectedProtocolFee &&
            netInputAmount == outputAmount + feeAmount + protocolFeeAmount
        );
    }

    receive() external payable {}
}

