contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseToken,
        address nft,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        require(feeRate <= 5_000);

        bool firstReverted;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            !firstReverted &&
            secondReverted &&
            c.baseToken() == baseToken &&
            c.nft() == nft &&
            c.virtualBaseTokenReserves() == vBase &&
            c.virtualNftReserves() == vNft &&
            c.changeFee() == changeFee &&
            c.feeRate() == feeRate &&
            c.merkleRoot() == merkleRoot &&
            c.useStolenNftOracle() == useOracle &&
            c.payRoyalties() == payRoy &&
            c.initialized()
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 inputAmount) public {
        uint128 vBase = c.virtualBaseTokenReserves();
        uint128 vNft = c.virtualNftReserves();
        uint16 feeRate = c.feeRate();

        require(vNft > 0);
        require(uint256(vNft) + uint256(inputAmount) <= type(uint256).max);

        uint256 grossOutput = uint256(vBase) * uint256(inputAmount) / (uint256(vNft) + uint256(inputAmount));

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(uint256(inputAmount));

        assert(
            uint256(netOutputAmount) + uint256(feeAmount) + uint256(protocolFeeAmount) == grossOutput &&
            feeAmount == grossOutput * uint256(feeRate) / 10_000
        );
    }

    receive() external payable {}
}

