contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address baseToken, address nft, uint128 vr, uint128 vn, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useOracle, bool payRoy) public {
        // Attempt a first initialization with arbitrary parameters.
        bool firstReverted;
        try c.initialize(baseToken, nft, vr, vn, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool initializedAfter = c.initialized();

        // A second initialization must ALWAYS revert (AlreadyInitialized),
        // regardless of the parameters.
        bool secondReverted;
        try c.initialize(baseToken, nft, vr, vn, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // Rule: initialize succeeds iff feeRate <= 5000; on success the pool is marked
        // initialized; and a second initialize must always revert.
        assert(
            firstReverted == (feeRate > 5_000)
            && initializedAfter == !firstReverted
            && secondReverted
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint16 newFeeRate) public {
        uint16 before = c.feeRate();

        bool reverted;
        try c.setFeeRate(newFeeRate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint16 after_ = c.feeRate();

        assert(reverted && after_ == before);
    }
}

