    function run(uint56 changeFee, uint256 inputAmount) public {
        require(inputAmount < 10 ** 40);

        c.initialize(
            address(0),
            address(0),
            1e18,
            1e18,
            changeFee,
            0,
            bytes32(0),
            false,
            false
        );

        uint256 flashFee = c.flashFee(address(0), 1);

        (uint256 feeAmount, ) = c.changeFeeQuote(inputAmount);

        uint256 expectedPerNft = uint256(changeFee) * 10 ** 14;

        assert(
            c.baseToken() == address(0) &&
            flashFee == expectedPerNft &&
            feeAmount == (inputAmount * expectedPerNft) / 10 ** 18
        );
    }
